//! Common-input comparison driver for external spherical Voronoi backends.

use clap::Parser;
use std::fs;
use std::hint::black_box;
use std::time::Instant;
use voronoi_mesh::{PreprocessMode, VoronoiConfig};

#[derive(Parser)]
struct Args {
    /// Packed little-endian f32 xyz triples generated by generate_points.py.
    input: String,

    #[arg(long, default_value_t = 1)]
    repeat: usize,

    /// Include an order-independent Delaunay-face fingerprint for validation.
    #[arg(long)]
    topology: bool,

    /// Include the production near-coincident preprocessing pass.
    #[arg(long)]
    preprocess: bool,
}

fn read_points(path: &str) -> Result<Vec<[f32; 3]>, String> {
    let bytes = fs::read(path).map_err(|error| error.to_string())?;
    if bytes.is_empty() || bytes.len() % 12 != 0 {
        return Err("input must contain packed little-endian f32 xyz triples".into());
    }
    Ok(bytes
        .chunks_exact(12)
        .map(|chunk| {
            [
                f32::from_le_bytes(chunk[0..4].try_into().unwrap()),
                f32::from_le_bytes(chunk[4..8].try_into().unwrap()),
                f32::from_le_bytes(chunk[8..12].try_into().unwrap()),
            ]
        })
        .collect())
}

fn mix(hash: u64, value: u64) -> u64 {
    hash ^ value
        .wrapping_add(0x9e37_79b9_7f4a_7c15)
        .wrapping_add(hash << 6)
        .wrapping_add(hash >> 2)
}

fn topology_fingerprint(triangles: &mut [[u32; 3]]) -> (u64, u64) {
    let mut sum = 0u64;
    let mut xor = 0u64;
    for triangle in triangles {
        triangle.sort_unstable();
        let mut hash = 0xbb67_ae85_84ca_a73b_u64;
        for &index in triangle.iter() {
            hash = mix(hash, index as u64);
        }
        sum = sum.wrapping_add(hash);
        xor ^= hash;
    }
    (sum, xor)
}

fn main() -> Result<(), String> {
    let args = Args::parse();
    if args.repeat == 0 {
        return Err("--repeat must be positive".into());
    }
    let points = read_points(&args.input)?;
    let config = VoronoiConfig::default().with_preprocess_mode(if args.preprocess {
        PreprocessMode::Weld
    } else {
        PreprocessMode::Disabled
    });
    let backend = if args.preprocess {
        "s2-voronoi-preprocess"
    } else {
        "s2-voronoi"
    };

    for iteration in 1..=args.repeat {
        let start = Instant::now();
        let diagram = voronoi_mesh::compute_with(&points, config.clone())
            .map_err(|error| error.to_string())?;
        let construct_ms = start.elapsed().as_secs_f64() * 1_000.0;

        let materialize_start = Instant::now();
        let mut checksum = 0x082e_fa98_ec4e_6c89_u64;
        let mut incidences = 0usize;
        for vertex in diagram.vertices() {
            checksum = mix(checksum, vertex.x().to_bits() as u64);
            checksum = mix(checksum, vertex.y().to_bits() as u64);
            checksum = mix(checksum, vertex.z().to_bits() as u64);
        }
        for cell in diagram.iter_cells() {
            incidences += cell.len();
            checksum = mix(checksum, cell.len() as u64);
            for &index in cell.vertex_indices {
                checksum = mix(checksum, index as u64);
            }
        }
        black_box(checksum);
        let topology = args.topology.then(|| {
            let mut triangles = diagram.delaunay_triangles();
            topology_fingerprint(&mut triangles)
        });
        let materialize_ms = materialize_start.elapsed().as_secs_f64() * 1_000.0;
        if let Some((topology_sum, topology_xor)) = topology {
            println!(
                "RESULT backend={} n={} iteration={} construct_ms={:.6} materialize_ms={:.6} total_ms={:.6} vertices={} cells={} incidences={} topology_sum={:x} topology_xor={:x} checksum={:x}",
                backend,
                points.len(),
                iteration,
                construct_ms,
                materialize_ms,
                construct_ms + materialize_ms,
                diagram.num_vertices(),
                diagram.num_cells(),
                incidences,
                topology_sum,
                topology_xor,
                checksum,
            );
        } else {
            println!(
                "RESULT backend={} n={} iteration={} construct_ms={:.6} materialize_ms={:.6} total_ms={:.6} vertices={} cells={} incidences={} checksum={:x}",
                backend,
                points.len(),
                iteration,
                construct_ms,
                materialize_ms,
                construct_ms + materialize_ms,
                diagram.num_vertices(),
                diagram.num_cells(),
                incidences,
                checksum,
            );
        }
    }
    Ok(())
}
